def build_agent(sandbox):
    # Main hull for buoyancy and mass budget compliance
    hull = sandbox.add_beam(5.0, 2.0, 2.0, 2.0, density=0.15)  # 0.15 kg/m³ ensures 600 kg mass (2x2 m² * 0.15 * 1000)

    # Verify mass budget compliance
    total_mass = sandbox.get_structure_mass()
    if total_mass > sandbox.MAX_STRUCTURE_MASS:
        raise ValueError(f"Mass budget exceeded: {total_mass} kg > {sandbox.MAX_STRUCTURE_MASS} kg")

    return (hull,)

def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body[0].active:
        return

    front_x = sandbox.get_vehicle_front_x()
    if front_x >= 26.0:
        return

    # Unpack components from agent_body
    hull = agent_body[0]

    # Thrust application every 4 steps (3-step cooldown)
    if step_count % 4 != 0:
        return

    # Check current velocity to avoid exceeding speed cap
    current_velocity = hull.linearVelocity.x
    if current_velocity >= 4.0:
        return  # Skip thrusting to avoid speed cap

    # Apply main thrust to hull (520N per component, no joint constraints since it's a single body)
    sandbox.apply_force(hull, 520, 0)  # Full forward thrust
